const marcarPago = async (g) => {
  if (!rangeAtual) return;
  if (!window.confirm(`Confirma que já repassou pra ${g.nome}?\n\nGorjeta: ${fmt(g.total_gorjeta)}\nComissão: ${fmt(g.total_comissao)}\nTotal: ${fmt(g.total_gorjeta + g.total_comissao)}`)) return;
  setMarcandoPago(g.garcom_id);
  try {
    await registrarRepasseGarcom(g.garcom_id, {
      de: rangeAtual.de,
      ate: rangeAtual.ate,
      valor_gorjeta: g.total_gorjeta,
      valor_comissao: g.total_comissao,
    });
    await buscar();
  } catch (e) { setErro(e.message); }
  finally { setMarcandoPago(null); }
};

