723	  async pagar(id: number, restaurantId: number, formaPagamento: string, gorjetaValor?: number, valorRecebido?: number) {
724	    if (!formaPagamento) throw new BadRequestException('Informe a forma de pagamento');
725	
726	    const comanda = await this.buscarComanda(id, restaurantId);
727	    if (comanda.status !== 'fechada_garcom' && comanda.status !== 'aberta') {
728	      throw new BadRequestException('Comanda já foi paga ou cancelada');
729	    }
730	
731	    const { data: itens } = await this.supabase.client.from('order_items').select('quantity, unit_price, products(name)').eq('order_id', id);
732	    const subtotal = (itens ?? []).reduce((acc: number, i: any) => acc + i.quantity * i.unit_price, 0);
733	    const totalFinal = subtotal - (comanda.desconto_valor ?? 0) + (comanda.acrescimo_valor ?? 0);
734	
735	    // Se já teve pagamento parcial (garçom ou caixa), só registra o que ainda falta —
736	    // o ledger de comanda_pagamentos fica completo pra conferência.
737	    const { saldo } = await this.salaoService.saldoDevedor(id);
738	    // Fechamento não cobre mais o saldo restante sozinho — o operador é obrigado a lançar
739	    // os pagamentos parciais (com a forma correta de cada um) até o saldo zerar antes de
740	    // poder fechar. Evita fechar tudo numa forma só quando o cliente pagou split.
741	    if (saldo > 0.01) {
742	      throw new BadRequestException('Saldo devedor pendente: registre os pagamentos até zerar o saldo antes de fechar a comanda');
743	    }
744	    const gorjeta = gorjetaValor ?? 0;
745	    const valorACobrarBase = parseFloat(gorjeta.toFixed(2));
746	    const taxaCartaoValor = await this.salaoService.calcularTaxaCartao(restaurantId, valorACobrarBase, formaPagamento);
747	    // A essa altura o saldo dos itens já está zerado — só falta cobrar a gorjeta (se houver).
748	    const valorACobrar = parseFloat((valorACobrarBase + taxaCartaoValor).toFixed(2));
749	    let troco: number | null = null;
750	    if (formaPagamento === 'cash' && valorRecebido !== undefined) {
751	      if (valorRecebido < valorACobrar) throw new BadRequestException('Valor recebido não pode ser menor que o valor a pagar');
752	      troco = parseFloat((valorRecebido - valorACobrar).toFixed(2));
753	    }
754	
755	    if (formaPagamento === 'cash') {
756	      const identificador = `Comanda #${comanda.numero_comanda ?? id}`;
757	      if (troco && troco > 0) await this.salaoService.registrarSaidaCaixa(restaurantId, `Troco - ${identificador}`, troco, 'troco');
758	    }
759	
760	    // Se a comanda ficou pendente (fiado) num caixa que já fechou, realoca pro caixa
761	    // que estiver aberto agora, no momento do pagamento — não fica presa a um caixa fechado.
762	    let caixaId = comanda.caixa_id;
763	    if (caixaId) {
764	      const { data: caixaAtual } = await this.supabase.client
765	        .from('caixas').select('status').eq('id', caixaId).maybeSingle();
766	      if (caixaAtual?.status !== 'aberto') caixaId = null;
767	    }
768	    if (!caixaId) {
769	      const { data: caixaAberto } = await this.supabase.client
770	        .from('caixas')
771	        .select('id')
772	        .eq('restaurant_id', restaurantId)
773	        .eq('status', 'aberto')
774	        .maybeSingle();
775	      caixaId = caixaAberto?.id ?? null;
776	    }
777	
778	    const { error } = await this.supabase.client
779	      .from('orders')
780	      .update({
781	        status: 'paga',
782	        payment_method: formaPagamento,
783	        total: parseFloat(totalFinal.toFixed(2)),
784	        gorjeta_valor: gorjetaValor ?? null,
785	        caixa_id: caixaId,
786	        pago_em: new Date().toISOString(),
787	      })
788	      .eq('id', id);
789	    if (error) throw error;
790	
791	    if (comanda.mesa_id) {
792	      await this.supabase.client.from('mesas').update({ status: 'livre' }).eq('id', comanda.mesa_id);
793	    }
794	
795	    await this.lancarComissoes(comanda, subtotal, totalFinal);
796	
797	    const { data: pagamentos } = await this.supabase.client
798	      .from('comanda_pagamentos')
799	      .select('valor, forma_pagamento, origem, taxa_cartao_valor')
800	      .eq('order_id', id)
801	      .order('criado_em', { ascending: true });
802	
803	    // Soma a taxa de TODOS os pagamentos da comanda (garçom + caixa, parciais e final) —
804	    // usar só taxaCartaoValor (da última parcela) subestimava o recibo quando já havia
805	    // pagamento parcial anterior em cartão.
