const FecharComandaModal = ({ comanda, onFechar, onFechada }) => {
  const [erro, setErro] = useState(null);
  const [salvando, setSalvando] = useState(false);

  const confirmar = async () => {
    const numero = comanda.numero_comanda ?? comanda.id;
    const cliente = comanda.cliente_mesa_nome ?? 'sem nome';
    if (!window.confirm(`Você tem certeza que quer fechar a comanda número ${numero} do cliente ${cliente}?`)) return;
    setErro(null);
    setSalvando(true);
    try {
      await fecharComanda(comanda.id);
      onFechada();
    } catch (err) {
      setErro(err.message ?? 'Não foi possível fechar a comanda.');
    } finally {
      setSalvando(false);
    }
  };

  return (
    <div className="fixed inset-0 bg-black/60 flex items-end sm:items-center justify-center z-50 p-4">
      <div className="bg-white rounded-2xl p-6 w-full max-w-sm shadow-2xl">
        <h2 className="text-base font-bold text-[#18181B] mb-1">Fechar comanda</h2>
        <p className="text-xs text-[#71717A] mb-4">

